class Solution:
    def constructRectangle(self, area: int) -> List[int]:
        best = None
        w = 1
        while w * w <= area:
            if area % w == 0:
                l = area // w
                if best is None or l - w < best[0] - best[1]:
                    best = [l, w]
            w += 1
        return best

