class Solution {
public:
    vector<int> constructRectangle(int area) {
        int bl = area, bw = 1;
        for (long long w = 1; w * w <= area; ++w) {
            if (area % w == 0) {
                long long l = area / w;
                if (l - w < bl - bw) { bl = l; bw = w; }
            }
        }
        return {(int)bl, (int)bw};
    }
};

